def part_banner(code, title, sub):
    br = 'break-before:page;' if code == '8A' else 'margin-top:26px;'
    return f'<div style="{br}break-inside:avoid;margin-bottom:20px;padding:22px 24px;border-radius:18px;background:linear-gradient(135deg,#0C3A28,#07200F);color:#fff"><div style="font:800 8pt Inter;letter-spacing:.28em;color:#C9FF48">PART {code}</div><div style="font:900 30px/1.05 \'Inter Display\';letter-spacing:-.025em;margin:6px 0 8px">{sq(title)}</div><div style="font:500 10.5pt/1.45 Inter;color:#CFE9D6">{sq(sub)}</div></div>'

def day_card(n, name, purpose, example, note, label):
    return f'''<div class="ws" style="margin:12px 0;break-inside:avoid"><div class="hd">DAY {n} · {name}</div>
<div style="padding:10px 16px 2px;font:500 9.6pt/1.5 Inter"><p style="margin-bottom:6px"><strong>Purpose:</strong> {sq(purpose)}</p>{"<p style=\"margin-bottom:6px;color:#2E3B33;font-family:Bitstream Charter,serif;font-style:italic\">"+sq(example)+"</p>" if example else ""}{"<p style=\"color:#5C6B62;margin-bottom:6px\">"+sq(note)+"</p>" if note else ""}</div>
<div class="q" style="border-top:1px solid #E3EDE6"><b>{sq(label)}</b>{LN(3)}</div></div>'''

